results = {}

for p in range(1, 6):
    for q in range(1, 6):
        max_n = 0
        best_s_for_pq = -float('inf')
        found_n = False

        # Iterate n downwards from 12 to find the maximum n satisfying S < 1
        for n in range(12, 0, -1):
            # Calculate S
            S = (12 + n) / p + (13 - n) / q

            if S < 1:
                max_n = n
                # Calculate S for this max_n
                S_max = (12 + max_n) / p + (13 - max_n) / q
                best_s_for_pq = S_max
                found_n = True
                break  # Found the maximum n, move to the next (p, q)

        if found_n:
            results[(p, q)] = {
                "max_n": max_n,
                "max_S": best_s_for_pq
            }

# Format results for printing
print("--- Search Results ---")
for (p, q), data in results.items():
    print(f"P={p}, Q={q}: Max n = {data['max_n']}, Max S = {data['max_S']:.6f}")

print("\n--- Summary Dictionary ---")
print(results)
